  Drag the figure to orbit: the nested &ldquo;ellipses&rdquo; are true circles in planes
  perpendicular to the wire. Click the wire or a ring for an explanation.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element spec (built exactly as listed) ─────────────────────────────────
   wire            → CylinderGeometry(0.16,0.16,22) rot z 90°   MeshStandard #9aa0a6
   wire highlight  → CylinderGeometry(0.055,0.055,21.9) top     MeshBasic   #d8dce0
   fist palm       → SphereGeometry scaled                      skin #f2d0a9 + BackSide outline #c88f5e
   4 fingers       → TorusGeometry(R,0.17, arc 230°) in Y-Z      skin, wrapping over the wire
   knuckles        → SphereGeometry(0.2)                         skin
   thumb           → CylinderGeometry + tip Sphere along +X      skin
   wrist           → CylinderGeometry tilted down-left           skin
   current arrow   → Cylinder shaft + ConeGeometry head          #b02a2a
   4 ring sets     → 4 × TorusGeometry(r,0.035) rot y 90°        MeshBasic #1f7ac0
   ring arrowheads → ConeGeometry(0.09,0.26) tangent to ring     #1f7ac0
   radial marker   → TorusGeometry(r,0.045) + Cylinder spoke     #e8a33d
   labels          → addLabel: I , B vector , B readout
──────────────────────────────────────────────────────────────────────────── */

scene.add(new THREE.AmbientLight(0xffffff, 0.8));
const _dlA = new THREE.DirectionalLight(0xffffff, 0.55); _dlA.position.set(-4, 7, 9); scene.add(_dlA);
const _dlB = new THREE.DirectionalLight(0xffffff, 0.25); _dlB.position.set(5, -4, -7); scene.add(_dlB);

/* ── Wire ─────────────────────────────────────────────────────────────── */
const wireMat = new THREE.MeshStandardMaterial({ color: 0x9aa0a6, roughness: 0.32, metalness: 0.5 });
const wire = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.16, 22, 32), wireMat);
wire.rotation.z = Math.PI / 2;
scene.add(wire);
registerInteractive(wire, {
  title: 'Long straight wire',
  tooltip: 'The current-carrying wire',
  body: 'A steady current I flows along this wire. Its magnetic field has no component along the wire — the field lines are closed circles wrapped around it.'
});

const wireHL = new THREE.Mesh(
  new THREE.CylinderGeometry(0.055, 0.055, 21.9, 14),
  new THREE.MeshBasicMaterial({ color: 0xd8dce0 })
);
wireHL.rotation.z = Math.PI / 2;
wireHL.position.set(0, 0.115, 0.045);
scene.add(wireHL);

/* ── Stylized right hand gripping the wire at x = -6 ──────────────────── */
const skinMat = new THREE.MeshStandardMaterial({ color: 0xf2d0a9, roughness: 0.75, metalness: 0.0 });
const outMat = new THREE.MeshBasicMaterial({ color: 0xc88f5e, side: THREE.BackSide });

function skinned(geo, outlineScale) {
  const m = new THREE.Mesh(geo, skinMat);
  const o = new THREE.Mesh(geo, outMat);
  o.scale.setScalar(outlineScale || 1.05);
  m.add(o);
  return m;
}

const handGroup = new THREE.Group();
handGroup.position.set(-6, 0, 0);
scene.add(handGroup);

// palm / fist mass below and around the wire
const palm = skinned(new THREE.SphereGeometry(1, 26, 18), 1.04);
palm.scale.set(0.72, 1.02, 0.9);
palm.position.set(-0.05, -0.62, 0.05);
handGroup.add(palm);

// four fingers curling over the top of the wire and down the far side
const fingerData = [
  [-0.56, 0.60], [-0.19, 0.66], [0.18, 0.64], [0.55, 0.57]
];
for (const [fx, R] of fingerData) {
  const plane = new THREE.Group();          // rotates the ring into the Y-Z plane
  plane.rotation.y = Math.PI / 2;
  plane.position.x = fx;
  const arc = THREE.MathUtils.degToRad(225);
  const f = skinned(new THREE.TorusGeometry(R, 0.165, 12, 30, arc), 1.045);
  f.rotation.z = THREE.MathUtils.degToRad(-22);   // start slightly behind-bottom
  plane.add(f);
  handGroup.add(plane);
  const knuckle = skinned(new THREE.SphereGeometry(0.2, 16, 12), 1.06);
  knuckle.position.set(fx, R * 0.96, 0.04);
  handGroup.add(knuckle);
}

// extended thumb along +X (current direction), just below the wire
const thumb = skinned(new THREE.CylinderGeometry(0.17, 0.15, 1.25, 14), 1.06);
thumb.position.set(0.95, -0.42, 0.45);
thumb.rotation.z = Math.PI / 2;
thumb.rotation.x = -0.18;
handGroup.add(thumb);
const thumbTip = skinned(new THREE.SphereGeometry(0.18, 14, 12), 1.07);
thumbTip.position.set(1.58, -0.40, 0.40);
handGroup.add(thumbTip);
const thumbBase = skinned(new THREE.SphereGeometry(0.26, 16, 12), 1.06);
thumbBase.position.set(0.32, -0.5, 0.5);
handGroup.add(thumbBase);

// wrist
const wrist = skinned(new THREE.CylinderGeometry(0.5, 0.42, 1.3, 16), 1.05);
wrist.position.set(-0.55, -1.75, 0.0);
wrist.rotation.z = 0.32;
handGroup.add(wrist);

registerInteractive(palm, {
  title: 'Right-hand rule',
  tooltip: 'Right-hand rule',
  body: 'Point the right thumb along the current I; the curled fingers then give the direction in which the magnetic field circles the wire.'
});

/* ── Red current arrow + label ────────────────────────────────────────── */
const redMat = new THREE.MeshBasicMaterial({ color: 0xb02a2a });
const curArrow = new THREE.Group();
curArrow.position.set(-2.6, -0.30, 0.02);
scene.add(curArrow);
const curShaft = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.045, 0.85, 10), redMat);
curShaft.rotation.z = -Math.PI / 2;
curShaft.position.set(-0.175, 0, 0);
curArrow.add(curShaft);
const curHead = new THREE.Mesh(new THREE.ConeGeometry(0.12, 0.35, 14), redMat);
curHead.rotation.z = -Math.PI / 2;
curHead.position.set(0.425, 0, 0);
curArrow.add(curHead);

/* ── Four ring sets ───────────────────────────────────────────────────── */
const RING_R = [0.5, 0.95, 1.6, 2.5];
const SET_X = [1, 4, 7, 10];
const ringMat = new THREE.MeshBasicMaterial({ color: 0x1f7ac0 });
const arrowHeads = [];
const UPV = new THREE.Vector3(0, 1, 0);

for (const sx of SET_X) {
  const g = new THREE.Group();
  g.position.x = sx;
  scene.add(g);
  RING_R.forEach((r, i) => {
    const t = new THREE.Mesh(new THREE.TorusGeometry(r, 0.035, 8, 96), ringMat);
    t.rotation.y = Math.PI / 2;
    g.add(t);
    if (i === 0 && sx === SET_X[1]) {
      registerInteractive(t, {
        title: 'Magnetic field line',
        tooltip: 'A field line: a circle around the wire',
        body: 'Each blue curve is a closed circle centred on the wire, lying in a plane perpendicular to it. The rings crowd near the wire because B is strongest there and falls off as 1/r.'
      });
    }
    const angs = i >= 2 ? [115, 295] : [115];
    for (const ad of angs) {
      const a = THREE.MathUtils.degToRad(ad);
      const pos = new THREE.Vector3(0, r * Math.cos(a), r * Math.sin(a));
      const tan = new THREE.Vector3(0, -Math.sin(a), Math.cos(a)).normalize();
      const radial = new THREE.Vector3(0, Math.cos(a), Math.sin(a)).normalize();
      const cone = new THREE.Mesh(new THREE.ConeGeometry(0.095, 0.27, 14), ringMat);
      cone.position.copy(pos);
      const baseQuat = new THREE.Quaternion().setFromUnitVectors(UPV, tan);
      cone.quaternion.copy(baseQuat);
      g.add(cone);
      arrowHeads.push({ mesh: cone, radial, baseQuat });
    }
  });
}

/* ── Radial marker (amber ring + spoke) at x = 7 ──────────────────────── */
const MARK_X = 7;
const amberMat = new THREE.MeshBasicMaterial({ color: 0xe8a33d });
const markGroup = new THREE.Group();
markGroup.position.set(MARK_X, 0, 0);
scene.add(markGroup);

let markRing = new THREE.Mesh(new THREE.TorusGeometry(1, 0.045, 8, 96), amberMat);
markRing.rotation.y = Math.PI / 2;
markGroup.add(markRing);

const spokeDir = new THREE.Vector3(0, 1, 0.35).normalize();
const spokePivot = new THREE.Group();
spokePivot.quaternion.setFromUnitVectors(UPV, spokeDir);
markGroup.add(spokePivot);
const spoke = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 1, 10), amberMat);
spoke.position.y = 0.5;
spokePivot.add(spoke);
const spokeDot = new THREE.Mesh(new THREE.SphereGeometry(0.08, 12, 10), amberMat);
spokePivot.add(spokeDot);

function setMarkerRadius(wr) {
  markRing.geometry.dispose();
  markRing.geometry = new THREE.TorusGeometry(wr, 0.045, 8, 96);
  spoke.scale.y = wr;
  spoke.position.y = wr / 2;
  spokeDot.position.y = wr;
}

/* ── Camera (perspective, after all geometry) ─────────────────────────── */
setCameraView({
  projection: 'perspective',
  azimuthDeg: 75,      // 15° three-quarter offset from the wire-perpendicular view
  elevationDeg: 12,
  rollDeg: 0,
  heightFraction: 0.6
