  rollDeg: 0,
  heightFraction: 0.6
});
controls.minAzimuthAngle = THREE.MathUtils.degToRad(-45);
controls.maxAzimuthAngle = THREE.MathUtils.degToRad(95);
controls.minPolarAngle = THREE.MathUtils.degToRad(45);
controls.maxPolarAngle = THREE.MathUtils.degToRad(110);
