btnL.addEventListener('click', () => setDirection(false));

/* ── Controls: radius slider ──────────────────────────────────────────── */
const slider = document.getElementById('radius');
slider.addEventListener('input', () => { state.rTarget = parseFloat(slider.value); });

/* ── Camera tween (used by the tour) ──────────────────────────────────── */
let camTween = null;
function tweenCamera(thetaDeg, polarDeg, dur) {
  const sph = new THREE.Spherical().setFromVector3(
    camera.position.clone().sub(controls.target));
  camTween = {
    t0: performance.now(), dur: dur || 900,
    from: { theta: sph.theta, phi: sph.phi }, radius: sph.radius,
    to: { theta: THREE.MathUtils.degToRad(thetaDeg), phi: THREE.MathUtils.degToRad(polarDeg) }
  };
}

/* ── Guided tour ──────────────────────────────────────────────────────── */
const steps = [
  {
    title: '1. Right hand grips the wire',
    narr: 'The thumb of the right hand points along the current I to the right; the curled fingers show the blue field circles wrapping the wire in that same sense.',
    right: true, r: 1.5, cam: [15, 78]
  },
  {
    title: '2. Reverse the current',
    narr: 'Flip I to the left: the thumb turns around and every arrowhead on every ring reverses. Field circulation is tied rigidly to current direction.',
    right: false, r: 1.5, cam: [15, 78]
  },
  {
    title: '3. Move away from the wire',
    narr: 'The highlighted loop jumps out into the widely spaced outer rings and the B readout falls as 1/r.',
    right: true, r: 6, cam: [15, 78]
  },
  {
    title: '4. Look along the wire',
    narr: 'Orbit toward the wire axis: the nested ellipses resolve into true concentric circles in planes perpendicular to the wire.',
    right: true, r: 3, cam: [88, 84]
  }
];
let stepIdx = 0;
function goToStep(i) {
  stepIdx = ((i % steps.length) + steps.length) % steps.length;
  const s = steps[stepIdx];
  setDirection(s.right);
  state.rTarget = s.r;
  slider.value = String(s.r);
  tweenCamera(s.cam[0], s.cam[1], 1000);
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepNarr').textContent = s.narr;
}
document.getElementById('stepNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('stepPrev').addEventListener('click', () => goToStep(stepIdx - 1));
goToStep(0);

/* ── Update loop (separate from the scaffold render loop) ─────────────── */
let _lastT = performance.now();
(function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(64, now - _lastT); _lastT = now;

  // current reversal: continuous 400 ms flip
  if (state.flip !== state.flipTarget) {
    const step = dt / 400;
    const dir = Math.sign(state.flipTarget - state.flip);
    state.flip += dir * step;
    if ((dir > 0 && state.flip >= state.flipTarget) || (dir < 0 && state.flip <= state.flipTarget)) {
      state.flip = state.flipTarget;
    }
    applyFlip(state.flip);
  }

  // radius easing
  if (Math.abs(state.rCm - state.rTarget) > 0.002) {
    state.rCm += (state.rTarget - state.rCm) * Math.min(1, dt / 120);
    applyRadius(state.rCm);
  }

  // camera tween
  if (camTween) {
    const u = Math.min(1, (now - camTween.t0) / camTween.dur);
    const e = u < 0.5 ? 2 * u * u : -1 + (4 - 2 * u) * u;
    const th = camTween.from.theta + (camTween.to.theta - camTween.from.theta) * e;
    const ph = camTween.from.phi + (camTween.to.phi - camTween.from.phi) * e;
    const sph = new THREE.Spherical(camTween.radius, ph, th);
    camera.position.setFromSpherical(sph).add(controls.target);
    camera.lookAt(controls.target);
    controls.update();
    if (u >= 1) camTween = null;
  }
})();
// @FIGURE_CODE_END

