// @FIGURE_CODE_BEGIN
/* ── Element spec (built exactly as listed) ─────────────────────────────────
   wire            → CylinderGeometry(0.16,0.16,22) rot z 90°   MeshStandard #9aa0a6
   wire highlight  → CylinderGeometry(0.045,0.045,21.8)         MeshBasic    #d8dce0
   hand: dorsum / palm / thenar / heel → scaled SphereGeometry  skin #f2d0a9 + BackSide outline #c88f5e
   hand: wrist     → CylinderGeometry tapered, down-left        skin
   4 fingers       → 3 tapered CylinderGeometry phalanges + SphereGeometry joints, curled far→top→near
   fingernails     → flattened SphereGeometry on distal phalanx #faf0e0
   thumb           → 2 tapered Cylinders + Spheres along +X     skin
   current arrow   → CylinderGeometry shaft + ConeGeometry head #b02a2a
   4 ring sets     → 4 × TorusGeometry(r,0.035) rot y 90°       MeshBasic #1f7ac0
   ring arrowheads → ConeGeometry(0.12,0.34) tangent to ring    #1f7ac0
   radial marker   → TorusGeometry(r,0.05) + spoke Cylinder + dot  #e8a33d
   labels          → addLabel: I , B (with overbar arrow) , r/B readout
──────────────────────────────────────────────────────────────────────────── */

/* ── Lighting ─────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.74));
const _keyL = new THREE.DirectionalLight(0xffffff, 0.55); _keyL.position.set(-2, 6, 9); scene.add(_keyL);
const _filL = new THREE.DirectionalLight(0xffffff, 0.24); _filL.position.set(5, -4, -7); scene.add(_filL);

/* ── Wire ─────────────────────────────────────────────────────────────── */
const wireMat = new THREE.MeshStandardMaterial({ color: 0x9aa0a6, roughness: 0.32, metalness: 0.55 });
const wire = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.16, 22, 40), wireMat);
wire.rotation.z = Math.PI / 2;
scene.add(wire);
registerInteractive(wire, {
  title: 'Long straight wire',
  tooltip: 'The current-carrying wire',
  body: 'A steady current I flows along this wire. Its magnetic field has no component along the wire — the field lines are closed circles wrapped around it, lying in planes perpendicular to the wire.'
});
const wireHL = new THREE.Mesh(
  new THREE.CylinderGeometry(0.045, 0.045, 21.8, 12),
  new THREE.MeshBasicMaterial({ color: 0xd8dce0 })
);
wireHL.rotation.z = Math.PI / 2;
wireHL.position.set(0, 0.112, 0.055);
scene.add(wireHL);

/* ── Stylized right hand gripping the wire ────────────────────────────── */
const matSkin = new THREE.MeshStandardMaterial({ color: 0xf2d0a9, roughness: 0.88, metalness: 0 });
const matSkin2 = new THREE.MeshStandardMaterial({ color: 0xe9c49c, roughness: 0.88, metalness: 0 });
const matNail = new THREE.MeshStandardMaterial({ color: 0xfaf0e0, roughness: 0.45, metalness: 0 });
const matOut = new THREE.MeshBasicMaterial({ color: 0xc88f5e, side: THREE.BackSide });

const handGroup = new THREE.Group();
handGroup.position.set(-6.5, 0, 0);
scene.add(handGroup);

function withOutline(mesh, sx, sy, sz) {
  const o = new THREE.Mesh(mesh.geometry, matOut);
  o.scale.set(sx, sy === undefined ? sx : sy, sz === undefined ? sx : sz);
  mesh.add(o);
  return mesh;
}
function blob(sx, sy, sz, x, y, z, mat) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(1, 26, 18), mat || matSkin);
  m.scale.set(sx, sy, sz);
  m.position.set(x, y, z);
  withOutline(m, 1.035);
  handGroup.add(m);
  return m;
}
function limb(p0, p1, r0, r1, mat) {
  const dv = new THREE.Vector3().subVectors(p1, p0);
  const len = Math.max(dv.length(), 1e-4);
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r1, r0, len, 16, 1), mat || matSkin);
  m.position.copy(p0).addScaledVector(dv, 0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dv.clone().normalize());
  withOutline(m, 1.11, 0.98, 1.11);
  handGroup.add(m);
  return m;
}
function joint(p, r, mat) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(r, 18, 12), mat || matSkin);
  m.position.copy(p);
  withOutline(m, 1.06);
  handGroup.add(m);
  return m;
}
// phi = 0 → far side (-Z), 90° → top (+Y), 180° → near side (+Z), 230° → near-bottom
function fpos(x, phiDeg, R) {
  const p = THREE.MathUtils.degToRad(phiDeg);
  return new THREE.Vector3(x, R * Math.sin(p), -R * Math.cos(p));
}

// palm masses (fingertips tuck into the palm mass, so it reads as a closed fist)
const dorsum = blob(1.15, 0.95, 0.62, -0.02, -0.25, -0.92);            // back of hand, far side
const palm = blob(1.14, 1.05, 0.88, -0.05, -1.30, 0.02);             // palm, below wire
const thenar = blob(0.62, 0.80, 0.60, 0.78, -1.05, 0.50);             // thumb muscle
const heel = blob(0.95, 0.62, 0.72, -0.20, -2.12, -0.10);            // heel of hand
limb(new THREE.Vector3(-0.35, -2.30, -0.15), new THREE.Vector3(-1.25, -3.35, -0.25), 0.72, 0.60);

// four curled fingers — same grip radius so they form one finger mass, not nested rings
const FINGERS = [
  { x: 0.95, tip: 224, t: 0.96, R: 0.98 },   // index (next to thumb)
  { x: 0.32, tip: 232, t: 1.03, R: 1.03 },   // middle
  { x: -0.31, tip: 228, t: 1.00, R: 1.00 },   // ring
  { x: -0.93, tip: 216, t: 0.86, R: 0.92 }    // little
];
const fingerMids = [];
for (const f of FINGERS) {
  const angs = [-10, 60, 130, f.tip];
  const Rs = [1.32, 1.30, 1.16, 0.95].map(v => v * f.R);
  const ts = [0.300, 0.285, 0.245, 0.195].map(v => v * f.t);
  const pts = angs.map((a, i) => fpos(f.x, a, Rs[i]));
  for (let i = 0; i < 3; i++) fingerMids.push(limb(pts[i], pts[i + 1], ts[i], ts[i + 1], matSkin2));
  for (let i = 0; i < 4; i++) joint(pts[i], ts[i] * (i === 0 ? 1.14 : 1.02), matSkin2);
  // fingernail on the outer face of the distal phalanx
  const nailA = (130 + f.tip) / 2 - 6;
  const nailR = (Rs[2] + Rs[3]) / 2;
  const outward = fpos(0, nailA, 1).normalize();
  const nail = new THREE.Mesh(new THREE.SphereGeometry(1, 14, 10), matNail);
  nail.scale.set(0.155 * f.t, 0.05, 0.125 * f.t);
  nail.position.copy(fpos(f.x, nailA, nailR)).addScaledVector(outward, ts[3] * 0.80);
  nail.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), outward);
  handGroup.add(nail);
}

// extended thumb along +X (the current direction), just below the wire
const th0 = new THREE.Vector3(0.80, -1.10, 0.58);
const th1 = new THREE.Vector3(1.52, -0.92, 0.74);
const th2 = new THREE.Vector3(2.18, -0.72, 0.72);
limb(th0, th1, 0.32, 0.28);
limb(th1, th2, 0.28, 0.225);
joint(th0, 0.33); joint(th1, 0.275); joint(th2, 0.225);
const thNail = new THREE.Mesh(new THREE.SphereGeometry(1, 14, 10), matNail);
thNail.scale.set(0.10, 0.05, 0.13);
thNail.position.set(2.11, -0.62, 0.86);
thNail.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), new THREE.Vector3(0.2, 0.5, 0.85).normalize());
handGroup.add(thNail);

const handInfo = {
  title: 'Right-hand rule',
  tooltip: 'Right-hand rule — grip the wire',
  body: 'Point the right thumb along the current I. The curled fingers then sweep the way the magnetic field circles the wire: up the far side, over the top, and down the near side when I points to the right.'
};
[palm, dorsum, thenar, heel, fingerMids[1], fingerMids[4], fingerMids[7]].forEach(m => registerInteractive(m, handInfo));

/* ── Red current arrow ────────────────────────────────────────────────── */
const redMat = new THREE.MeshBasicMaterial({ color: 0xb02a2a });
const curArrow = new THREE.Group();
curArrow.position.set(-2.6, -0.55, 0);
scene.add(curArrow);
const curShaft = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.055, 0.85, 12), redMat);
curShaft.rotation.z = -Math.PI / 2;
curShaft.position.set(-0.22, 0, 0);
curArrow.add(curShaft);
const curHead = new THREE.Mesh(new THREE.ConeGeometry(0.16, 0.42, 16), redMat);
curHead.rotation.z = -Math.PI / 2;
curHead.position.set(0.41, 0, 0);
curArrow.add(curHead);
registerInteractive(curHead, {
  title: 'Conventional current I',
  tooltip: 'Current direction',
  body: 'The red arrow marks the direction of the conventional current, I = 10 A here. Reverse it and the hand turns around and every blue field arrow reverses with it.'
});

/* ── Four identical ring sets ─────────────────────────────────────────── */
const RING_R = [0.5, 0.95, 1.6, 2.5];
const SET_X = [1, 4, 7, 10];
const ringMat = new THREE.MeshBasicMaterial({ color: 0x1f7ac0 });
const arrowHeads = [];
const UPV = new THREE.Vector3(0, 1, 0);

for (const sx of SET_X) {
  const g = new THREE.Group();
  g.position.x = sx;
  scene.add(g);
  RING_R.forEach((r, i) => {
    const t = new THREE.Mesh(new THREE.TorusGeometry(r, 0.035, 10, 120), ringMat);
    t.rotation.y = Math.PI / 2;        // ring plane ⟂ wire
    g.add(t);
    if (i >= 2 && sx === SET_X[1]) {
      registerInteractive(t, {
        title: 'Magnetic field line',
        tooltip: 'A field line: a circle around the wire',
        body: 'Each blue curve is a closed circle centred on the wire in a plane perpendicular to it. The circles crowd together near the wire, where B is large, and spread apart outward because B falls off as 1/r.'
      });
    }
    const angs = i >= 2 ? [112, 292] : [112];
    for (const ad of angs) {
      const a = THREE.MathUtils.degToRad(ad);
      const pos = new THREE.Vector3(0, r * Math.cos(a), r * Math.sin(a));
      const tan = new THREE.Vector3(0, -Math.sin(a), Math.cos(a)).normalize();
      const radial = new THREE.Vector3(0, Math.cos(a), Math.sin(a)).normalize();
      const cone = new THREE.Mesh(new THREE.ConeGeometry(0.12, 0.34, 16), ringMat);
      cone.position.copy(pos);
      const baseQuat = new THREE.Quaternion().setFromUnitVectors(UPV, tan);
      cone.quaternion.copy(baseQuat);
      g.add(cone);
      arrowHeads.push({ mesh: cone, radial, baseQuat });
    }
  });
}

/* ── Radial marker (amber ring + spoke) at x = 7 ──────────────────────── */
const MARK_X = 7;
const amberMat = new THREE.MeshBasicMaterial({ color: 0xe8a33d });
const markGroup = new THREE.Group();
markGroup.position.set(MARK_X, 0, 0);
scene.add(markGroup);

let markRing = new THREE.Mesh(new THREE.TorusGeometry(1, 0.05, 10, 120), amberMat);
markRing.rotation.y = Math.PI / 2;
markGroup.add(markRing);
registerInteractive(markRing, {
  title: 'Sampled field loop',
  tooltip: 'The loop at the chosen radius r',
  body: 'This amber circle is the field line at the distance r set by the slider. B has the same magnitude everywhere on it, B = μ₀I/(2πr).'
});

const spokeDir = new THREE.Vector3(0, 1, 0.35).normalize();
const spokePivot = new THREE.Group();
spokePivot.quaternion.setFromUnitVectors(UPV, spokeDir);
markGroup.add(spokePivot);
const spoke = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.04, 1, 10), amberMat);
spoke.position.y = 0.5;
spokePivot.add(spoke);
const spokeDot = new THREE.Mesh(new THREE.SphereGeometry(0.1, 14, 10), amberMat);
spokePivot.add(spokeDot);

function setMarkerRadius(wr) {
  markRing.geometry.dispose();
  markRing.geometry = new THREE.TorusGeometry(wr, 0.05, 10, 120);
  spoke.scale.y = wr;
  spoke.position.y = wr / 2;
  spokeDot.position.y = wr;
}

/* ── Camera: true perspective, wire levelled to the source's horizontal ─ */
const VIEW_ALONG = { az: 14, el: 14, roll: 0, hf: 0.55 };
let curView = { az: 62, el: 11, roll: 0, hf: 0.62 };

function applyView(v) {
  setCameraView({
    projection: 'perspective',
    azimuthDeg: v.az, elevationDeg: v.el, rollDeg: v.roll,
    heightFraction: v.hf
  });
}
function wireScreenAngleDeg() {
  const a = new THREE.Vector3(-8, 0, 0).project(camera);
  const b = new THREE.Vector3(8, 0, 0).project(camera);
  const w = canvas.clientWidth || 1, h = canvas.clientHeight || 1;
  return THREE.MathUtils.radToDeg(Math.atan2(-(b.y - a.y) * h, (b.x - a.x) * w));
}
// Solve the roll that makes the wire exactly horizontal on screen.
function solveLevelRoll(v) {
  applyView({ ...v, roll: 0 });
  const a0 = wireScreenAngleDeg();
  applyView({ ...v, roll: 2 });
  const a1 = wireScreenAngleDeg();
  const s = (a1 - a0) / 2;
  let r = Math.abs(s) > 1e-4 ? -a0 / s : 0;
  if (!Number.isFinite(r)) r = 0;
  return Math.max(-30, Math.min(30, r));
}

applyView(curView);
camera.fov = 26;                       // mild, believable perspective convergence
camera.updateProjectionMatrix();
let BASE_ROLL = solveLevelRoll(curView);
curView.roll = BASE_ROLL;
applyView(curView);

controls.minAzimuthAngle = THREE.MathUtils.degToRad(-15);
controls.maxAzimuthAngle = THREE.MathUtils.degToRad(100);
controls.minPolarAngle = THREE.MathUtils.degToRad(48);
controls.maxPolarAngle = THREE.MathUtils.degToRad(112);
document.getElementById('btnReset').style.display = '';

// Re-level after a window resize (pixel aspect changes the on-screen angle).
let _relevelT = null;
window.addEventListener('resize', () => {
  if (_userMovedCamera) return;
  clearTimeout(_relevelT);
  _relevelT = setTimeout(() => {
    if (_userMovedCamera || curView.az < 30) return;
    BASE_ROLL = solveLevelRoll({ ...curView, roll: 0 });
    curView.roll = BASE_ROLL;
    applyView(curView);
  }, 80);
});

/* ── Labels (sized against the perspective label scaling) ─────────────── */
const _LK = camera.position.distanceTo(controls.target) / 8;
const fs = px => (px * _LK).toFixed(0) + 'px';

addLabel('<i>I</i>', new THREE.Vector3(-2.75, -1.25, 0),
  { color: '#b02a2a', fontSize: fs(17), bold: true });

addLabel(
  '<span style="display:inline-block;line-height:1;text-align:center">' +
  '<span style="display:block;font-size:0.60em;letter-spacing:-0.05em">&#8594;</span>' +
  '<span style="display:block;font-weight:700;font-style:italic">B</span></span>',
  new THREE.Vector3(10, 3.25, 0), { color: '#111', fontSize: fs(21) });

const labB = addLabel('', new THREE.Vector3(MARK_X, 1, 0),
  { color: '#8a5a12', fontSize: fs(11.5), bold: true, background: 'rgba(255,255,255,0.88)' });

/* ── State, reversal animation, readout ───────────────────────────────── */
const state = { flip: 0, flipTarget: 0, rCm: 1.5, rTarget: 1.5 };
const _q = new THREE.Quaternion();

function applyFlip(t) {
  handGroup.rotation.y = Math.PI * t;   // rigid 180° turn: still a right hand
  curArrow.rotation.y = Math.PI * t;
  for (const a of arrowHeads) {
    _q.setFromAxisAngle(a.radial, Math.PI * t);
    a.mesh.quaternion.copy(_q).multiply(a.baseQuat);
  }
}
function applyRadius(rCm) {
  const wr = 0.42 * rCm;
  setMarkerRadius(wr);
  const tip = spokeDir.clone().multiplyScalar(wr + 0.3);
  labB.pos.set(MARK_X + tip.x, tip.y, tip.z);
  const B = 200 / rCm;                  // B(µT) = 2e-7·I/r with I = 10 A, r in cm
  const bTxt = B >= 100 ? B.toFixed(0) : B.toFixed(1);
  labB.div.innerHTML = '<i>r</i> = ' + rCm.toFixed(1) + ' cm &nbsp; <i>B</i> = ' + bTxt + ' &micro;T';
  document.getElementById('rVal').textContent = rCm.toFixed(1);
  document.getElementById('bOut').innerHTML = 'B = ' + bTxt + ' &micro;T';
}
applyFlip(0);
applyRadius(1.5);

/* ── Control: current direction toggle ────────────────────────────────── */
const btnR = document.getElementById('dirR');
const btnL = document.getElementById('dirL');
function setDirection(rightward) {
  state.flipTarget = rightward ? 0 : 1;
  btnR.classList.toggle('active', rightward);
  btnL.classList.toggle('active', !rightward);
}
btnR.addEventListener('click', () => setDirection(true));
btnL.addEventListener('click', () => setDirection(false));

/* ── Control: radius slider ───────────────────────────────────────────── */
const slider = document.getElementById('radius');
slider.addEventListener('input', () => { state.rTarget = parseFloat(slider.value); });

/* ── View tween used by the tour ──────────────────────────────────────── */
let viewTween = null;
function tweenView(to, dur) {
  viewTween = { t0: performance.now(), dur: dur || 950, from: { ...curView }, to: { ...curView, ...to } };
}

/* ── Guided tour ──────────────────────────────────────────────────────── */
const steps = [
  {
    title: '1. Right hand grips the wire',
    narr: 'The thumb of the right hand points along the current I to the right; the curled fingers show the blue field circles wrapping the wire in that same sense — up the far side, over the top, down toward you.',
    right: true, r: 1.5, view: null
  },
  {
    title: '2. Reverse the current',
    narr: 'Flip I to the left: the hand turns around, the thumb follows the current, and every arrowhead on every ring reverses. Circulation is locked to current direction.',
    right: false, r: 1.5, view: null
  },
  {
    title: '3. Move away from the wire',
    narr: 'The amber loop moves out into the widely spaced outer rings and the readout falls as 1/r: 133 µT at 1.5 cm becomes just 33 µT at 6 cm.',
    right: true, r: 6, view: null
  },
  {
    title: '4. Look along the wire',
    narr: 'Orbit toward the wire axis: the nested "ellipses" resolve into true concentric circles in planes perpendicular to the wire.',
    right: true, r: 3, view: VIEW_ALONG
  }
];
let stepIdx = 0;
function goToStep(i, animateView) {
  stepIdx = ((i % steps.length) + steps.length) % steps.length;
  const s = steps[stepIdx];
  setDirection(s.right);
  state.rTarget = s.r;
  slider.value = String(s.r);
  if (animateView !== false) {
    tweenView(s.view ? s.view : { az: 62, el: 11, roll: BASE_ROLL, hf: 0.62 }, 1000);
  }
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepNarr').textContent = s.narr;
}
document.getElementById('stepNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('stepPrev').addEventListener('click', () => goToStep(stepIdx - 1));
goToStep(0, false);   // open in the authored figure pose, no swing

/* ── Update loop (separate from the scaffold render loop) ─────────────── */
let _lastT = performance.now();
(function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(64, now - _lastT); _lastT = now;

  // current reversal: continuous ~420 ms flip
  if (state.flip !== state.flipTarget) {
    const step = dt / 420;
    const dir = Math.sign(state.flipTarget - state.flip);
    state.flip += dir * step;
    if ((dir > 0 && state.flip >= state.flipTarget) || (dir < 0 && state.flip <= state.flipTarget)) {
      state.flip = state.flipTarget;
    }
    applyFlip(state.flip);
  }

  // radius easing
  if (Math.abs(state.rCm - state.rTarget) > 0.002) {
    state.rCm += (state.rTarget - state.rCm) * Math.min(1, dt / 120);
    applyRadius(state.rCm);
  }

  // view tween
  if (viewTween) {
    const u = Math.min(1, (now - viewTween.t0) / viewTween.dur);
    const e = u < 0.5 ? 2 * u * u : -1 + (4 - 2 * u) * u;
    const f = viewTween.from, t = viewTween.to;
    curView = {
      az: f.az + (t.az - f.az) * e,
      el: f.el + (t.el - f.el) * e,
      roll: f.roll + (t.roll - f.roll) * e,
      hf: f.hf + (t.hf - f.hf) * e
    };
    applyView(curView);
    if (u >= 1) viewTween = null;
  }
})();
